// Sentientia LMS Live — wordcloud updater — Phase E.5.
//
// Listens for the 'sentientia-live:response_added' CustomEvent
// (dispatched by audience_sse / trainer_sse) and re-renders the
// wordcloud panel in place via wordcloud_loader.render(). Updates only
// textContent + className — never innerHTML — so this is XSS-safe
// even if the SSE payload is tampered with.
//
// chart_updater.js owns multichoice / quiz / rating; this module owns
// wordcloud. Both attach a listener for the same event; each early-
// returns when the slide_type isn't its own.
//
// Built as named-define ES5 for the bundled context.
define('local_sentientia_live/wordcloud_updater', [
    'local_sentientia_live/wordcloud_loader'
], function(Loader) {
    'use strict';

    function init() {
        window.addEventListener(
            'sentientia-live:response_added', handleResponseAdded);
    }

    function handleResponseAdded(ev) {
        if (!ev.detail) { return; }
        var slideId   = ev.detail.slide_id;
        var slideType = ev.detail.slide_type;
        var tally     = ev.detail.tally;
        var countNow  = ev.detail.count_now;
        if (slideType !== 'wordcloud') { return; }

        var panel = document.querySelector(
            '.sentientia-results-panel[data-slideid="' + slideId + '"]');
        if (!panel) { return; }

        var totalEl = panel.querySelector('.sentientia-results-total');
        if (totalEl && typeof countNow === 'number') {
            totalEl.textContent = String(countNow);
        }

        // P0 #8 — sr-only tally summary aria-live region.
        var summaryEl = panel.querySelector('[data-live-tally-summary]');
        if (summaryEl && typeof countNow === 'number') {
            var suffix = panel.dataset.a11yTallySuffix || '';
            summaryEl.textContent = String(countNow)
                + (suffix ? ' ' + suffix : '');
        }

        if (!tally || typeof tally !== 'object') { return; }
        Loader.render(panel, tally);
    }

    return {
        init: init
    };
});
